+        TYPE_LABELS.put("breaking-java", "Breaking Java changes");
+        TYPE_LABELS.put("bug", "Bug fixes");
+        TYPE_LABELS.put("deprecation", "Deprecations");
+        TYPE_LABELS.put("enhancement", "Enhancements");
