+        changelogsByVersionByTypeByArea.forEach(
+            (_version, byVersion) -> byVersion.forEach(
+                (_type, byTeam) -> byTeam.forEach(
+                    (_team, changelogsForTeam) -> changelogsForTeam.sort(Comparator.comparing(ChangelogEntry::getSummary))
+                )
+            )
+        );
