+
+    @Override
+    public Stream<Field<?>> fields(String fieldGlob) {
+        return Stream.empty();
+    }
+
+    @Override
+    public void setDocument(int docID) {
+        leafLookup.setDocument(docID);
+    }
+
+    @Override
+    public Map<String, Object> docAsMap() {
+        return leafLookup.asMap();
+    }
+
+    @Override
+    public Map<String, ScriptDocValues<?>> doc() {
